// Suppliers sheet rows -> lookup object keyed by website_url
const rows = $input.all();
const map = {};
for (const item of rows) {
  const r = item.json;
  if (!r.website_url) continue;
  map[r.website_url] = {
    login_workflow_id: r.login_workflow_id,
    parser_workflow_id: r.parser_workflow_id
  };
}
return [{ json: map }];

// Fresh per-job context. Feeds is re-read on EVERY iteration, so a profile saved by an
// earlier job in this run is visible to later jobs of the same feed (no stale map, no
// repeated logins for the same feed within one run).
const job = $('Loop Over Items').first().json;
const suppliers = $('Build Suppliers Map').first().json;
const feeds = $input.all().map(i => i.json);
const feed = feeds.find(f => f.feed_id && String(f.feed_id).trim() === String(job.feed_id).trim());
if (!feed) {
  return [{ json: { infra_error: "feed_id '" + job.feed_id + "' not found in Feeds sheet" } }];
}
const supplier = suppliers[feed.website_url];
if (!supplier || !supplier.login_workflow_id || !supplier.parser_workflow_id) {
  return [{ json: { infra_error: "Suppliers sheet has no login/parser workflow for website_url '" + feed.website_url + "'" } }];
}
const profileId = String(feed.browser_profile_id || '').trim();
return [{ json: {
  feed_id: String(feed.feed_id).trim(),
  booking_id: job.booking_id,
  row_number: job.row_number,
  website_url: feed.website_url,
  bitwarden_item_id_input: feed.bitwarden_item_id_input,
  agent_code: feed.agent_code || '',
  browser_profile_id: profileId,
  had_profile: !!profileId,
  login_workflow_id: supplier.login_workflow_id,
  parser_workflow_id: supplier.parser_workflow_id
} }];

// Normalizes the entry item into the login chain. Entered from two places:
// bootstrap (no profile in Feeds yet) and recovery (parser attempt with an existing
// profile failed). The previous parser attempt travels in the item itself instead of
// $('Node').isExecuted, so every reference stays scoped to THIS loop iteration.
const j = $input.first().json || {};
return [{ json: {
  is_recovery: !!j.parser_run_id,
  prev_parser_run_id: j.parser_run_id || '',
  prev_parser_status: j.final_status || '',
  login_started_at: new Date().toISOString()
} }];

// Normalize the login run result. timed_out IS a final Skyvern status; anything still
// not final after the wait limit is an n8n-side timeout.
const run = $input.first().json;
const state = $('Build Job State').first().json;
const FINAL = ['completed', 'failed', 'terminated', 'canceled', 'timed_out'];
const login_status = run.status === 'completed' ? 'completed' : (FINAL.includes(run.status) ? 'failed' : 'timeout');
// The first-ever login for a profile key may report the created profile only in
// browser_sink_profile_id (browser_profile_id can be null on that run) — coalesce.
const new_profile_id = run.browser_sink_profile_id || run.browser_profile_id || '';
return [{ json: {
  login_status: login_status,
  login_run_id: $('Dispatch Login').first().json.workflow_run_id,
  new_profile_id: new_profile_id,
  profile_id_for_sheet: new_profile_id || state.browser_profile_id || ''
} }];

// Login failed or timed out — the job is final. Uses only same-iteration references:
// Login Context / Login Outcome always ran on this path in this iteration.
const state = $('Build Job State').first().json;
const lo = $('Login Outcome').first().json;
const ctx = $('Login Context').first().json;
const ui = $('Config').first().json.uiBaseUrl;
const label = state.had_profile ? 'profile expired' : 'no profile';
const recovered = label + (lo.login_status === 'timeout' ? ' — login timed out' : ' — login failed');
return [{ json: {
  row_number: state.row_number,
  final_status: 'failed',
  recovered_via_login: recovered,
  workflow_run_id: ctx.prev_parser_run_id,
  extracted_data: '',
  parser_run_url: ctx.prev_parser_run_id ? ui + '/runs/' + ctx.prev_parser_run_id : '',
  login_run_url: lo.login_run_id ? ui + '/runs/' + lo.login_run_id : ''
} }];

// Single convergence point right before Dispatch Parser. Downstream nodes read the
// current attempt from here — it re-runs before EVERY parser dispatch in this
// iteration, so its data can never leak in from a previous loop iteration.
const j = $input.first().json || {};
return [{ json: {
  profile_id: j.profile_id || '',
  allow_login_recovery: j.allow_login_recovery === true || j.allow_login_recovery === 'true',
  login_attempted: j.login_attempted === true || j.login_attempted === 'true',
  login_run_id: j.login_run_id || '',
  attempt_started_at: j.attempt_started_at || new Date().toISOString()
} }];

// Normalize the parser run result and bundle it with the attempt state so downstream
// IF/Finalize nodes only ever read $json (no cross-iteration node references).
const run = $input.first().json;
const attempt = $('Prepare Attempt').first().json;
const state = $('Build Job State').first().json;
const FINAL = ['completed', 'failed', 'terminated', 'canceled', 'timed_out'];
let final_status;
if (run.status === 'completed') final_status = 'completed';
else if (FINAL.includes(run.status)) final_status = 'failed';
else final_status = 'timeout';
let extracted = '';
const info = run.outputs && run.outputs.extracted_information;
if (info) { const first = Array.isArray(info) ? info[0] : info; extracted = JSON.stringify(first ?? info); }
return [{ json: {
  final_status: final_status,
  skyvern_status: run.status || '',
  failure_reason: run.failure_reason || '',
  extracted_data: extracted,
  parser_run_id: $('Dispatch Parser').first().json.workflow_run_id,
  profile_id: attempt.profile_id,
  allow_login_recovery: attempt.allow_login_recovery,
  login_attempted: attempt.login_attempted,
  login_run_id: attempt.login_run_id,
  had_profile: state.had_profile,
  row_number: state.row_number
} }];

// Build the final Jobs row from the (bundled) parser outcome only — $json carries
// everything, including whether a login ran in THIS iteration.
const o = $input.first().json;
const ui = $('Config').first().json.uiBaseUrl;
const label = o.had_profile ? 'profile expired' : 'no profile';
let recovered;
if (!o.login_attempted) {
  if (o.final_status === 'completed') recovered = 'not needed';
  else if (o.final_status === 'timeout') recovered = 'parser timed out (no recovery attempted)';
  else recovered = 'parser failed (no recovery attempted)';
} else {
  if (o.final_status === 'completed') recovered = label + ' — logged in, parser succeeded';
  else if (o.final_status === 'timeout') recovered = label + ' — logged in, but retry timed out';
  else recovered = label + ' — logged in, but parser still failed';
}
return [{ json: {
  row_number: o.row_number,
  final_status: o.final_status,
  recovered_via_login: recovered,
  workflow_run_id: o.parser_run_id,
  extracted_data: o.extracted_data,
  parser_run_url: ui + '/runs/' + o.parser_run_id,
  login_run_url: o.login_run_id ? ui + '/runs/' + o.login_run_id : ''
} }];
